import logging
import os
import re
import importlib.util
import importlib.machinery
from taf.config.testline import TestLine  # type: ignore

UTE_USER = "/home/ute/"
GERRIT_PATH = os.path.join(UTE_USER, "testline_configuration")


def get_tl_config(logger: logging.Logger) -> TestLine:
    """
    Fetch testline configuration base on testline location and name.
    :param logger: Logger that will be used to log messages
    :raise ValueError
    :return: Testline configuration as 'kind of' dict
    """
    tl_name = get_tl_name()
    logger.info(f"TL name: {tl_name}")
    module_path = get_config_module_path(tl_name)
    config = load_tl_config(module_path, tl_name)
    return config.tl


def load_tl_config(module_path: str, tl_name: str) -> TestLine:
    loader = importlib.machinery.SourceFileLoader(tl_name, module_path)
    spec = importlib.util.spec_from_loader(loader.name, loader)
    mod = importlib.util.module_from_spec(spec)  # type: ignore
    loader.exec_module(mod)
    return mod


def get_config_module_path(tl_name: str) -> str:
    return os.path.join(GERRIT_PATH, tl_name, "__init__.py")


def get_tl_name() -> str:
    """
    Return testline name.
    :raise: AttributeError
    :return: testline name
    :rtype: str
    """
    tl_name = os.uname().nodename
    if tl_name:
        return _parse_tl_name(tl_name)
    raise AttributeError(f"Could not get testline name. {os.uname()}")


def _parse_tl_name(tl_name: str) -> str:
    """
    Parse testline name to fulfill naming conventions.
    :param tl_name: testline name
    :type tl_name: str
    :return: parsed testline name
    """
    not_single_testline = re.search(r"-\d+$", tl_name)  # name end with number
    if not_single_testline:
        tl_name = tl_name[: not_single_testline.start()]
    tl_name = tl_name.replace("-", "_")
    return tl_name
